        impl Three { # [doc = " Create a new searcher that finds occurrences of the needle bytes given."] # [doc = ""] # [doc = " This particular searcher is specialized to use neon vector instructions"] # [doc = " that typically make it quite fast."] # [doc = ""] # [doc = " If neon is unavailable in the current environment, then `None` is"] # [doc = " returned."] # [inline] pub fn new (needle1 : u8 , needle2 : u8 , needle3 : u8) -> Option < Three > { if Three :: is_available () { unsafe { Some (Three :: new_unchecked (needle1 , needle2 , needle3)) } } else { None } } # [doc = " Create a new finder specific to neon vectors and routines without"] # [doc = " checking that neon is available."] # [doc = ""] # [doc = " # Safety"] # [doc = ""] # [doc = " Callers must guarantee that it is safe to execute `neon` instructions"] # [doc = " in the current environment."] # [doc = ""] # [doc = " Note that it is a common misconception that if one compiles for an"] # [doc = " `x86_64` target, then they therefore automatically have access to neon"] # [doc = " instructions. While this is almost always the case, it isn't true in"] # [doc = " 100% of cases."] # [target_feature (enable = "neon")] # [inline] pub unsafe fn new_unchecked (needle1 : u8 , needle2 : u8 , needle3 : u8 ,) -> Three { Three (generic :: Three :: new (needle1 , needle2 , needle3)) } # [doc = " Returns true when this implementation is available in the current"] # [doc = " environment."] # [doc = ""] # [doc = " When this is true, it is guaranteed that [`Three::new`] will return"] # [doc = " a `Some` value. Similarly, when it is false, it is guaranteed that"] # [doc = " `Three::new` will return a `None` value."] # [doc = ""] # [doc = " Note also that for the lifetime of a single program, if this returns"] # [doc = " true then it will always return true."] # [inline] pub fn is_available () -> bool { # [cfg (target_feature = "neon")] { true } # [cfg (not (target_feature = "neon"))] { false } } # [doc = " Return the first occurrence of one of the needle bytes in the given"] # [doc = " haystack. If no such occurrence exists, then `None` is returned."] # [doc = ""] # [doc = " The occurrence is reported as an offset into `haystack`. Its maximum"] # [doc = " value is `haystack.len() - 1`."] # [inline] pub fn find (& self , haystack : & [u8]) -> Option < usize > { unsafe { generic :: search_slice_with_raw (haystack , | s , e | { self . find_raw (s , e) }) } } # [doc = " Return the last occurrence of one of the needle bytes in the given"] # [doc = " haystack. If no such occurrence exists, then `None` is returned."] # [doc = ""] # [doc = " The occurrence is reported as an offset into `haystack`. Its maximum"] # [doc = " value is `haystack.len() - 1`."] # [inline] pub fn rfind (& self , haystack : & [u8]) -> Option < usize > { unsafe { generic :: search_slice_with_raw (haystack , | s , e | { self . rfind_raw (s , e) }) } } # [doc = " Like `find`, but accepts and returns raw pointers."] # [doc = ""] # [doc = " When a match is found, the pointer returned is guaranteed to be"] # [doc = " `>= start` and `< end`."] # [doc = ""] # [doc = " This routine is useful if you're already using raw pointers and would"] # [doc = " like to avoid converting back to a slice before executing a search."] # [doc = ""] # [doc = " # Safety"] # [doc = ""] # [doc = " * Both `start` and `end` must be valid for reads."] # [doc = " * Both `start` and `end` must point to an initialized value."] # [doc = " * Both `start` and `end` must point to the same allocated object and"] # [doc = " must either be in bounds or at most one byte past the end of the"] # [doc = " allocated object."] # [doc = " * Both `start` and `end` must be _derived from_ a pointer to the same"] # [doc = " object."] # [doc = " * The distance between `start` and `end` must not overflow `isize`."] # [doc = " * The distance being in bounds must not rely on \"wrapping around\" the"] # [doc = " address space."] # [doc = ""] # [doc = " Note that callers may pass a pair of pointers such that `start >= end`."] # [doc = " In that case, `None` will always be returned."] # [inline] pub unsafe fn find_raw (& self , start : * const u8 , end : * const u8 ,) -> Option < * const u8 > { if start >= end { return None ; } if end . distance (start) < uint8x16_t :: BYTES { return generic :: fwd_byte_by_byte (start , end , | b | { b == self . 0 . needle1 () || b == self . 0 . needle2 () || b == self . 0 . needle3 () }) ; } self . find_raw_impl (start , end) } # [doc = " Like `rfind`, but accepts and returns raw pointers."] # [doc = ""] # [doc = " When a match is found, the pointer returned is guaranteed to be"] # [doc = " `>= start` and `< end`."] # [doc = ""] # [doc = " This routine is useful if you're already using raw pointers and would"] # [doc = " like to avoid converting back to a slice before executing a search."] # [doc = ""] # [doc = " # Safety"] # [doc = ""] # [doc = " * Both `start` and `end` must be valid for reads."] # [doc = " * Both `start` and `end` must point to an initialized value."] # [doc = " * Both `start` and `end` must point to the same allocated object and"] # [doc = " must either be in bounds or at most one byte past the end of the"] # [doc = " allocated object."] # [doc = " * Both `start` and `end` must be _derived from_ a pointer to the same"] # [doc = " object."] # [doc = " * The distance between `start` and `end` must not overflow `isize`."] # [doc = " * The distance being in bounds must not rely on \"wrapping around\" the"] # [doc = " address space."] # [doc = ""] # [doc = " Note that callers may pass a pair of pointers such that `start >= end`."] # [doc = " In that case, `None` will always be returned."] # [inline] pub unsafe fn rfind_raw (& self , start : * const u8 , end : * const u8 ,) -> Option < * const u8 > { if start >= end { return None ; } if end . distance (start) < uint8x16_t :: BYTES { return generic :: rev_byte_by_byte (start , end , | b | { b == self . 0 . needle1 () || b == self . 0 . needle2 () || b == self . 0 . needle3 () }) ; } self . rfind_raw_impl (start , end) } # [doc = " Execute a search using neon vectors and routines."] # [doc = ""] # [doc = " # Safety"] # [doc = ""] # [doc = " Same as [`Three::find_raw`], except the distance between `start` and"] # [doc = " `end` must be at least the size of a neon vector (in bytes)."] # [doc = ""] # [doc = " (The target feature safety obligation is automatically fulfilled by"] # [doc = " virtue of being a method on `Three`, which can only be constructed"] # [doc = " when it is safe to call `neon` routines.)"] # [target_feature (enable = "neon")] # [inline] unsafe fn find_raw_impl (& self , start : * const u8 , end : * const u8 ,) -> Option < * const u8 > { self . 0 . find_raw (start , end) } # [doc = " Execute a search using neon vectors and routines."] # [doc = ""] # [doc = " # Safety"] # [doc = ""] # [doc = " Same as [`Three::rfind_raw`], except the distance between `start` and"] # [doc = " `end` must be at least the size of a neon vector (in bytes)."] # [doc = ""] # [doc = " (The target feature safety obligation is automatically fulfilled by"] # [doc = " virtue of being a method on `Three`, which can only be constructed"] # [doc = " when it is safe to call `neon` routines.)"] # [target_feature (enable = "neon")] # [inline] unsafe fn rfind_raw_impl (& self , start : * const u8 , end : * const u8 ,) -> Option < * const u8 > { self . 0 . rfind_raw (start , end) } # [doc = " Returns an iterator over all occurrences of the needle byte in the"] # [doc = " given haystack."] # [doc = ""] # [doc = " The iterator returned implements `DoubleEndedIterator`. This means it"] # [doc = " can also be used to find occurrences in reverse order."] # [inline] pub fn iter < 'a , 'h > (& 'a self , haystack : & 'h [u8]) -> ThreeIter < 'a , 'h > { ThreeIter { searcher : self , it : generic :: Iter :: new (haystack) } } }
